From 92d8f371553b88e5b3a9d3354e93f75d60d81368 Mon Sep 17 00:00:00 2001
From: Jason Lowe <jlowe@apache.org>
Date: Mon, 29 Aug 2016 15:55:38 +0000
Subject: [PATCH] HADOOP-13552. RetryInvocationHandler logs all remote
 exceptions. Contributed by Jason Lowe


diff --git a/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/io/retry/RetryInvocationHandler.java b/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/io/retry/RetryInvocationHandler.java
index 7bd3a15c4bf..c657d20709d 100644
--- a/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/io/retry/RetryInvocationHandler.java
+++ b/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/io/retry/RetryInvocationHandler.java
@@ -351,9 +351,11 @@ private RetryInfo handleException(final Method method, final int callId,
     if (retryInfo.isFail()) {
       // fail.
       if (retryInfo.action.reason != null) {
-        LOG.warn("Exception while invoking call #" + callId + " "
-            + proxyDescriptor.getProxyInfo().getString(method.getName())
-            + ". Not retrying because " + retryInfo.action.reason, e);
+        if (LOG.isDebugEnabled()) {
+          LOG.debug("Exception while invoking call #" + callId + " "
+              + proxyDescriptor.getProxyInfo().getString(method.getName())
+              + ". Not retrying because " + retryInfo.action.reason, e);
+        }
       }
       throw e;
     }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by excessive logging of remote exceptions at the warning level, which could lead to log clutter and make it difficult to identify critical issues. The original implementation logged all exceptions as warnings, regardless of their severity, which was not appropriate for all scenarios. This change aims to improve log management by only logging these exceptions at the debug level when detailed information is needed for troubleshooting.

        Commit message:
        HADOOP-13552. RetryInvocationHandler logs all remote
 exceptions. Contributed by Jason Lowe  

        Patch:

   private RetryInfo handleException(final Method method, final int callId,
       final RetryPolicy policy, final Counters counters,
       final long expectFailoverCount, final Exception e) throws Exception {
     final RetryInfo retryInfo = RetryInfo.newRetryInfo(policy, e,
         counters, proxyDescriptor.idempotentOrAtMostOnce(method),
         expectFailoverCount);
     if (retryInfo.isFail()) {
       // fail.
       if (retryInfo.action.reason != null) {
-        LOG.warn("Exception while invoking call #" + callId + " "
-            + proxyDescriptor.getProxyInfo().getString(method.getName())
-            + ". Not retrying because " + retryInfo.action.reason, e);
+        if (LOG.isDebugEnabled()) {
+          LOG.debug("Exception while invoking call #" + callId + " "
+              + proxyDescriptor.getProxyInfo().getString(method.getName())
+              + ". Not retrying because " + retryInfo.action.reason, e);
+        }
       }
       throw e;
     }

     log(method, retryInfo.isFailover(), counters.failovers, retryInfo.delay, e);
     return retryInfo;
   }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
